package cz.mares.wavecal

object NameDaysData {

    fun getNameDay(countryCode: String, monthZeroBased: Int, dayOfMonth: Int): String {
        if (countryCode == "none") return ""
        val table = when (countryCode.lowercase()) {
            "cz" -> cz
            "sk" -> sk
            "pl" -> pl
            "de" -> de
            "en" -> en
            else -> cz
        }
        val monthList = table.getOrNull(monthZeroBased) ?: return ""
        return monthList.getOrNull(dayOfMonth - 1) ?: ""
    }

